문 14. 다음 C++ 프로그램의 실행 결과는?
#include <iostream.h>
void ErrorHandler(int test)
{
try {
if (test) throw test;
else throw "예외 발생";
}
catch(int i) {
cout << "예외에서 잡은 숫자 : " << i << "\n";
}
catch(char *str) {
cout << "예외에서 잡은 문자열 : " << str << "\n";
throw;
}
}
int main(int argc, char* argv[])
{
try {
ErrorHandler(1);
ErrorHandler(0);
ErrorHandler(2);
}
catch(char *) {
cout << "메인함수에서 잡은 예외 \n";
}
return 0;
}

